1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const BASE_PREMIUMS: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	  moonstone: 25,
63	};
64	
65	const BLOCK_SIZE = 3;
66	const BLOCK_PREMIUM = 60;
67	
68	const isBlock = (sameTypeItems: Item[]): boolean =>
69	  sameTypeItems.length === BLOCK_SIZE;
70	
71	const basePremiumOfItem = (item: Item): number => BASE_PREMIUMS[item.type];
72	
73	const sumOfItemBasePremiums = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + basePremiumOfItem(item), 0);
75	
76	const groupByType = (items: Item[]): Item[][] =>
77	  Object.values(
78	    items.reduce<Record<string, Item[]>>(
79	      (groups, item) => ({
80	        ...groups,
81	        [item.type]: [...(groups[item.type] ?? []), item],
82	      }),
83	      {},
84	    ),
85	  );
86	
87	const basePremiumOfGroup = (items: Item[]): number =>
88	  isBlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
89	
90	const policyBasePremium = (items: Item[]): number =>
91	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
92	
93	const CURSED_SURCHARGE_RATE = 0.5;
94	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
95	
96	const HIGH_ENCHANTMENT_THRESHOLD = 5;
97	
98	const isCursed = (item: Item): boolean => item.cursed === true;
99	
100	const UNENCHANTED = 0;
101	
102	const enchantmentOf = (item: Item): number => item.enchantment ?? UNENCHANTED;
103	
104	const isHighlyEnchanted = (item: Item): boolean =>
105	  enchantmentOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
106	
107	const NO_SURCHARGE_RATE = 0;
108	
109	const surchargeRateOfItem = (item: Item): number =>
110	  (isCursed(item) ? CURSED_SURCHARGE_RATE : NO_SURCHARGE_RATE) +
111	  (isHighlyEnchanted(item)
112	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
113	    : NO_SURCHARGE_RATE);
114	
115	const surchargeOfItem = (item: Item): number =>
116	  basePremiumOfItem(item) * surchargeRateOfItem(item);
117	
118	const sumOfItemSurcharges = (items: Item[]): number =>
119	  items.reduce((sum, item) => sum + surchargeOfItem(item), 0);
120	
121	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
122	
123	const firstInsuranceSurcharge = (basePremium: number): number =>
124	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
125	
126	const roundPremiumInMHPCOsFavour = (premium: number): number =>
127	  Math.ceil(premium);
128	
129	const LOYALTY_DISCOUNT_RATE = 0.2;
130	const LOYALTY_YEARS_THRESHOLD = 2;
131	const NO_DISCOUNT = 0;
132	
133	const isLoyal = (customer: Customer): boolean =>
134	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
135	
136	const loyaltyDiscount = (customer: Customer, basePremium: number): number =>
137	  isLoyal(customer) ? basePremium * LOYALTY_DISCOUNT_RATE : NO_DISCOUNT;
138	
139	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
140	
141	const isFollowUpContract = (previousQuoteCount: number): boolean =>
142	  previousQuoteCount > 0;
143	
144	const followUpContractDiscount = (
145	  previousQuoteCount: number,
146	  basePremium: number,
147	): number =>
148	  isFollowUpContract(previousQuoteCount)
149	    ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
150	    : NO_DISCOUNT;
151	
152	const quote = (
153	  items: Item[],
154	  customer: Customer,
155	  previousQuoteCount: number,
156	): QuoteResult => {
157	  const basePremium = policyBasePremium(items);
158	  const surcharges =
159	    sumOfItemSurcharges(items) + firstInsuranceSurcharge(basePremium);
160	  const discounts =
161	    loyaltyDiscount(customer, basePremium) +
162	    followUpContractDiscount(previousQuoteCount, basePremium);
163	  return {
164	    premium: roundPremiumInMHPCOsFavour(
165	      PROCESSING_FEE + basePremium + surcharges - discounts,
166	    ),
167	  };
168	};
169	
170	const DEDUCTIBLE = 100;
171	const INSURANCE_VALUES: Record<string, number> = {
172	  sword: 1000,
173	  amulet: 600,
174	  rune: 250,
175	};
176	const CAP_FACTOR = 2;
177	
178	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
179	const HALF_REIMBURSEMENT_RATE = 0.5;
180	const FULL_REIMBURSEMENT_RATE = 1;
181	
182	const damagedItem = (damage: Damage, policyItems: Item[]): Item =>
183	  policyItems.find((item) => item.type === damage.itemType)!;
184	
185	const isDeeplyEnchanted = (item: Item): boolean =>
186	  enchantmentOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
187	
188	const reimbursementRateOfItem = (item: Item): number =>
189	  isDeeplyEnchanted(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
190	
191	const payoutOfDamage = (damage: Damage, policyItems: Item[]): number =>
192	  damage.amount * reimbursementRateOfItem(damagedItem(damage, policyItems)) -
193	  DEDUCTIBLE;
194	
195	const payoutOfIncident = (incident: Incident, policyItems: Item[]): number =>
196	  incident.damages.reduce(
197	    (sum, damage) => sum + payoutOfDamage(damage, policyItems),
198	    0,
199	  );
200	
201	const insuranceSum = (items: Item[]): number =>
202	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
203	
204	const capOfPolicy = (policyItems: Item[]): number =>
205	  CAP_FACTOR * insuranceSum(policyItems);
206	
207	const claim = (
208	  incident: Incident,
209	  policyItems: Item[],
210	  availableCap: number,
211	): ClaimResult => {
212	  const payout = Math.floor(
213	    Math.min(payoutOfIncident(incident, policyItems), availableCap),
214	  );
215	  return {
216	    payout,
217	    remainingCap: availableCap - payout,
218	  };
219	};
220	
221	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
222	
223	const quoteSteps = (steps: Step[]): QuoteStep[] => steps.filter(isQuoteStep);
224	
225	const insuredItemsOfPolicy = (steps: Step[], policy: number): Item[] =>
226	  quoteSteps(steps)[policy].items;
227	
228	const quoteCountBefore = (steps: Step[], stepIndex: number): number =>
229	  quoteSteps(steps.slice(0, stepIndex)).length;
230	
231	type RemainingCaps = Record<number, number>;
232	
233	const availableCapOfPolicy = (
234	  remainingCaps: RemainingCaps,
235	  policyItems: Item[],
236	  policy: number,
237	): number => remainingCaps[policy] ?? capOfPolicy(policyItems);
238	
239	export const runScenario = (scenario: Scenario): ScenarioResult => {
240	  const remainingCaps: RemainingCaps = {};
241	  const results = scenario.steps.map((step, stepIndex) => {
242	    if (isQuoteStep(step)) {
243	      return quote(
244	        step.items,
245	        scenario.customer,
246	        quoteCountBefore(scenario.steps, stepIndex),
247	      );
248	    }
249	    const policyItems = insuredItemsOfPolicy(scenario.steps, step.policy);
250	    const result = claim(
251	      step.incident,
252	      policyItems,
253	      availableCapOfPolicy(remainingCaps, policyItems, step.policy),
254	    );
255	    remainingCaps[step.policy] = result.remainingCap;
256	    return result;
257	  });
258	  return { results };
259	};
